WITH hourly_returns AS (SELECT td.t_hour, 'catalog' AS source, cr.cr_return_amount AS return_amount FROM catalog_returns cr JOIN time_dim td ON cr.cr_returned_time_sk = td.t_time_sk UNION ALL SELECT td.t_hour, 'store' AS source, sr.sr_return_amt AS return_amount FROM store_returns sr JOIN time_dim td ON sr.sr_return_time_sk = td.t_time_sk), aggregated AS (SELECT t_hour, source, SUM(return_amount) AS total_return_amount FROM hourly_returns GROUP BY t_hour, source) SELECT t_hour, source, total_return_amount, AVG(total_return_amount) OVER (PARTITION BY source ORDER BY t_hour ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS rolling_3hr_avg, CASE WHEN total_return_amount = MAX(total_return_amount) OVER (PARTITION BY source) THEN 'PeakHour' ELSE 'NormalHour' END AS hour_category, RANK() OVER (PARTITION BY source ORDER BY total_return_amount DESC) AS amount_rank FROM aggregated ORDER BY source, amount_rank
